insert into public.learning_content
(content_id,faculty,subject,content_type,access_tier,display_order,content_data,is_published)
values
('dph-pharmchem-note-101','Pharmacy','Diploma in Pharmacy','note','free',201,'{"title":"Pharmaceutical Chemistry: Basic Concepts and Chemical Reactions","english":"Pharmaceutical chemistry studies the chemical properties, identification, purity, stability and quality of substances used as medicines. Core concepts include atoms, ions, chemical bonds, molecular formulae, molecular mass, oxidation-reduction, acids, bases and salts. Chemical reactions and functional groups help explain drug properties, incompatibilities and analytical tests.","nepali":"Pharmaceutical Chemistry मा औषधिका रूपमा प्रयोग हुने पदार्थको रासायनिक गुण, पहिचान, शुद्धता, stability र quality पढिन्छ। मुख्य आधारमा atom, ion, chemical bond, molecular formula, molecular mass, oxidation-reduction, acid, base र salt पर्छन्। Chemical reaction र functional group ले औषधिको गुण, incompatibility र परीक्षण बुझ्न मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmchem-note-102','Pharmacy','Diploma in Pharmacy','note','free',202,'{"title":"Acids, Bases, pH and Buffer Solutions","english":"An acid donates protons and a base accepts protons in the Brønsted-Lowry concept. pH expresses hydrogen-ion activity on a logarithmic scale; lower pH is more acidic and higher pH is more alkaline. A buffer solution resists changes in pH when small amounts of acid or base are added. Buffers commonly contain a weak acid and its conjugate base, or a weak base and its conjugate acid.","nepali":"Brønsted-Lowry अवधारणाअनुसार acid ले proton दिन्छ र base ले proton ग्रहण गर्छ। pH ले hydrogen-ion activity लाई logarithmic scale मा जनाउँछ; कम pH बढी acidic र बढी pH बढी alkaline हुन्छ। Buffer ले थोरै acid वा base थप्दा pH परिवर्तन हुनबाट रोक्न मद्दत गर्छ। सामान्य buffer मा weak acid र त्यसको conjugate base वा weak base र conjugate acid हुन्छ।"}'::jsonb,true),
('dph-pharmchem-note-103','Pharmacy','Diploma in Pharmacy','note','free',203,'{"title":"Solutions, Concentration and Pharmaceutical Calculations","english":"A solution is a homogeneous mixture of solute and solvent. Concentration may be expressed as percentage strength (% w/w, % w/v or % v/v), ratio strength, molarity or parts per million, depending on the context. Molarity is the number of moles of solute per litre of final solution. Use the correct molecular mass, units and final volume; distinguish dilution from mixing solutions of different concentrations.","nepali":"Solution भनेको solute र solvent को homogeneous mixture हो। Concentration लाई अवस्थाअनुसार percentage strength (% w/w, % w/v, % v/v), ratio strength, molarity वा parts per million मा व्यक्त गर्न सकिन्छ। Molarity भनेको अन्तिम solution को प्रति litre मा solute का mole को संख्या हो। Molecular mass, unit र अन्तिम volume सही राख्नुहोस्; dilution र फरक concentration भएका solution मिसाउने प्रक्रिया फरक हुन सक्छ।"}'::jsonb,true),
('dph-pharmchem-note-104','Pharmacy','Diploma in Pharmacy','note','free',204,'{"title":"Volumetric Analysis and Titration","english":"Volumetric analysis determines the amount or concentration of a substance by measuring the volume of a standard solution that reacts with it. In an acid-base titration, the equivalence point is the point at which stoichiometrically equivalent amounts have reacted; an indicator or instrumental method helps identify the endpoint. Accurate results require calibrated glassware, a suitable indicator, careful meniscus reading and repeatable technique.","nepali":"Volumetric analysis मा कुनै पदार्थसँग प्रतिक्रिया गर्ने standard solution को volume मापन गरेर त्यस पदार्थको मात्रा वा concentration पत्ता लगाइन्छ। Acid-base titration मा stoichiometric रूपमा बराबर मात्रा प्रतिक्रिया भएको बिन्दु equivalence point हो; indicator वा instrument ले endpoint पहिचान गर्न मद्दत गर्छ। सही नतिजाका लागि calibrated glassware, उपयुक्त indicator, meniscus सही पढ्ने र सावधानीपूर्वक दोहोर्‍याउन सकिने technique आवश्यक हुन्छ।"}'::jsonb,true),
('dph-pharmchem-note-105','Pharmacy','Diploma in Pharmacy','note','free',205,'{"title":"Pharmaceutical Inorganic Substances and Quality Tests","english":"Pharmaceutical inorganic substances include selected salts, electrolytes, antacids, adsorbents and topical or diagnostic agents. Their identity and quality are assessed using appropriate pharmacopoeial tests. Limit tests are designed to determine whether specified impurities, such as chloride, sulphate, iron or heavy metals, remain below defined limits. Always use the current official monograph and validated procedure rather than relying on memory for reagent details.","nepali":"Pharmaceutical inorganic substances मा केही salts, electrolytes, antacids, adsorbents तथा topical वा diagnostic agents पर्छन्। तिनको पहिचान र गुणस्तर उपयुक्त pharmacopoeial test बाट जाँचिन्छ। Limit test ले chloride, sulphate, iron वा heavy metals जस्ता impurity तोकिएको सीमाभन्दा कम छन् कि छैनन् जाँच्छ। Reagent को विवरण सम्झनामा मात्र भर नपरी हाल लागू official monograph र मान्य procedure प्रयोग गर्नुपर्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-101','Pharmacy','Diploma in Pharmacy','mcq','free',201,'{"question":"Which particle carries a negative electrical charge?","translation":"कुन कणमा ऋणात्मक विद्युतीय charge हुन्छ?","options":["Proton","Neutron","Electron","Nucleus"],"correctIndex":2,"explanation":"An electron carries a negative charge; a proton is positive and a neutron is neutral.","explanationNe":"Electron मा negative charge हुन्छ; proton positive र neutron neutral हुन्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-102','Pharmacy','Diploma in Pharmacy','mcq','free',202,'{"question":"A solution with pH 3 is best described as:","translation":"pH ३ भएको solution कस्तो हुन्छ?","options":["Acidic","Neutral","Alkaline","Always a buffer"],"correctIndex":0,"explanation":"A pH below 7 is acidic under the usual aqueous scale at 25°C.","explanationNe":"सामान्य aqueous scale मा २५°C मा pH ७ भन्दा कम भए acidic हुन्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-103','Pharmacy','Diploma in Pharmacy','mcq','free',203,'{"question":"What is the main function of a buffer solution?","translation":"Buffer solution को मुख्य काम के हो?","options":["Increase temperature","Resist sudden pH change","Remove all solute","Always make pH 7"],"correctIndex":1,"explanation":"A buffer resists pH change when small amounts of acid or base are added.","explanationNe":"थोरै acid वा base थप्दा pH धेरै परिवर्तन हुन नदिन buffer ले मद्दत गर्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-104','Pharmacy','Diploma in Pharmacy','mcq','free',204,'{"question":"Molarity is expressed as:","translation":"Molarity कसरी व्यक्त गरिन्छ?","options":["Moles per litre of solution","Grams per 100 g only","mL per 100 mL only","Mass per tablet"],"correctIndex":0,"explanation":"Molarity is moles of solute per litre of final solution.","explanationNe":"Molarity भनेको अन्तिम solution को प्रति litre मा solute का mole हुन्।"}'::jsonb,true),
('dph-pharmchem-mcq-105','Pharmacy','Diploma in Pharmacy','mcq','free',205,'{"question":"Which apparatus is designed to deliver a measured variable volume during titration?","translation":"Titration गर्दा नापिएको variable volume दिन कुन apparatus प्रयोग हुन्छ?","options":["Burette","Watch glass","Mortar","Evaporating dish"],"correctIndex":0,"explanation":"A burette delivers accurately measured variable volumes, commonly in titration.","explanationNe":"Burette ले titration मा आवश्यक नापिएको variable volume दिन्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-106','Pharmacy','Diploma in Pharmacy','mcq','free',206,'{"question":"The endpoint of an indicator-based titration is commonly recognized by:","translation":"Indicator प्रयोग भएको titration को endpoint सामान्यतया कसरी चिनिन्छ?","options":["A suitable colour change","A change in bottle shape","A rise in room temperature only","The solution becoming solid"],"correctIndex":0,"explanation":"A suitable indicator changes colour over a range near the equivalence point.","explanationNe":"उपयुक्त indicator ले equivalence point नजिक निश्चित pH range मा रंग परिवर्तन गर्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-107','Pharmacy','Diploma in Pharmacy','mcq','free',207,'{"question":"Which of the following is commonly used as an antacid?","translation":"तलका मध्ये कुन सामान्यतया antacid का रूपमा प्रयोग हुन्छ?","options":["Magnesium hydroxide","Sodium chloride","Potassium permanganate","Ferrous sulphate"],"correctIndex":0,"explanation":"Magnesium hydroxide neutralizes gastric acid and is used as an antacid.","explanationNe":"Magnesium hydroxide ले gastric acid neutralize गर्छ र antacid का रूपमा प्रयोग हुन्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-108','Pharmacy','Diploma in Pharmacy','mcq','free',208,'{"question":"A limit test is primarily used to:","translation":"Limit test मुख्यतया केका लागि प्रयोग हुन्छ?","options":["Check specified impurity against a limit","Measure tablet colour","Determine patient age","Calculate retail price"],"correctIndex":0,"explanation":"A limit test checks whether a specified impurity is within the permitted limit.","explanationNe":"Limit test ले तोकिएको impurity स्वीकार्य सीमाभित्र छ कि छैन जाँच्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-109','Pharmacy','Diploma in Pharmacy','mcq','free',209,'{"question":"Which unit relationship is correct?","translation":"कुन unit relationship सही छ?","options":["1 L = 100 mL","1 g = 100 mg","1 mg = 1000 micrograms","1 kg = 100 g"],"correctIndex":2,"explanation":"One milligram equals one thousand micrograms.","explanationNe":"१ milligram बराबर १००० microgram हुन्छ।"}'::jsonb,true),
('dph-pharmchem-mcq-110','Pharmacy','Diploma in Pharmacy','mcq','free',210,'{"question":"In an acid-base titration, the equivalence point occurs when:","translation":"Acid-base titration मा equivalence point कहिले हुन्छ?","options":["Stoichiometrically equivalent amounts have reacted","The burette is empty","The solution becomes colourless in every titration","The temperature reaches 100°C"],"correctIndex":0,"explanation":"At equivalence, reactants have combined in stoichiometrically equivalent amounts.","explanationNe":"Equivalence point मा reactant हरू stoichiometric रूपमा बराबर अनुपातमा प्रतिक्रिया गरिसकेका हुन्छन्।"}'::jsonb,true),
